pub fn print_matches(&self, items: &[AstGrepMatch]) -> Result<(), AstGrepError> {
        // Group by file path; BTreeMap gives deterministic file ordering.
        let mut groups: BTreeMap<&str, Vec<&AstGrepMatch>> = BTreeMap::new();
        for item in items {
            groups.entry(&item.file[..]).or_default().push(item);
        }

        // helper to format an optional byte range (e.g. "[start..end]")
        let format_range = |r: Option<&ByteRange>| -> String {
            match r {
                // ByteRange.start and .end are plain integers (e.g. u64), not Option.
                Some(br) => format!(" [{}..{}]", br.start, br.end),
                None => String::new(),
            }
        };

        for (file, mut matches) in groups {
            // file header
            println!("{}", file);
            println!("{}", "-".repeat(file.len().max(1)));

            // sort deterministically within a file:
            // first by name_text, then method_name, then impl_body
            matches.sort_by(|a, b| {
                a.method_name
                    .cmp(&b.method_name)
                    .then(a.impl_body.cmp(&b.impl_body))
                    .then(a.method_body.cmp(&b.method_body))
            });

            // helper to print a labeled field; first line is inline, following lines indented
            let print_field = |label: &str, value: &str, range: Option<&ByteRange>| {
                let range_suffix = format_range(range);
                if value.trim().is_empty() {
                    println!("{:<7} {}{}", label, "<no value>", range_suffix);
                    return;
                }
                let mut lines = value.lines();
                if let Some(first) = lines.next() {
                    println!("{:<7} {}{}", label, first, range_suffix);
                    for l in lines {
                        println!("        {}", l);
                    }
                } else {
                    println!("{:<7} {}{}", label, "<no value>", range_suffix);
                }
            };

            // print each match in the stable order
            for (idx, m) in matches.iter().enumerate() {
                println!("--- Match {} ---", idx + 1);

                // defensive fallback to readable placeholders (we still pass the original string
                // to print_field which handles empty/whitespace-only cases)
                let file_field: &str = if m.file.trim().is_empty() {
                    "<no file>"
                } else {
                    &m.file
                };
                let method_field: &str = if m.method_name.trim().is_empty() {
                    "<no method>"
                } else {
                    &m.method_name
                };
                let impl_field: &str = if m.impl_body.trim().is_empty() {
                    "<no impl>"
                } else {
                    &m.impl_body
                };

                let method_body: &str = if !m.method_body.trim().is_empty() {
                    &m.method_body
                } else {
                    "<no method>"
                };
                print_field("file:", file_field, None);
                print_field("method body:", method_body, None);
                print_field("method impl:", impl_field, Some(&m.impl_body_range));
                print_field("method name:", method_field, Some(&m.method_name_range));
            }

            // blank line between files for readability
            println!();
        }

        Ok(())
